package vn.svframe.lively.event;
import vn.svframe.lively.actor.ActorId;import vn.svframe.lively.actor.ActorRegistry;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public final class StorySeedEngine{public record Seed(String id,WorldEventEngine.Category category,double weight,boolean enabled,Map<String,String>rules){public Seed{Objects.requireNonNull(id);Objects.requireNonNull(category);weight=unit(weight);rules=Map.copyOf(rules);}}public record AntagonistCandidate(ActorId actor,double score,String reason,Map<String,String>facts){public AntagonistCandidate{score=unit(score);facts=Map.copyOf(facts);}}private final ConcurrentHashMap<String,Seed>seeds=new ConcurrentHashMap<>();public void register(Seed seed){seeds.put(seed.id(),seed);}public void remove(String id){seeds.remove(id);}public Map<String,Seed>snapshot(){return Map.copyOf(seeds);}public void restore(Map<String,Seed>s){seeds.clear();seeds.putAll(s);}public List<WorldEventEngine.EventProposal>propose(Map<String,Double>signals,String structureId,Set<ActorId>actors,int max){List<WorldEventEngine.EventProposal>out=new ArrayList<>();for(Seed seed:seeds.values().stream().filter(Seed::enabled).sorted(Comparator.comparingDouble(Seed::weight).reversed()).toList()){if(out.size()>=Math.max(0,Math.min(16,max)))break;double signal=unit(signals.getOrDefault(seed.id(),signals.getOrDefault(seed.category().name().toLowerCase(Locale.ROOT),0D))),score=signal*.7D+seed.weight()*.3D;if(score<.35D)continue;out.add(new WorldEventEngine.EventProposal(seed.category(),seed.id(),structureId,actors,score,java.time.Duration.ofMinutes(Math.max(10,Math.min(1440,Math.round(30+score*360)))),seed.rules()));}return List.copyOf(out);}public List<AntagonistCandidate>antagonistCandidates(ActorRegistry registry,Set<ActorId>candidates,Map<String,Double>signals){double crisis=unit(signals.getOrDefault("economic_crisis",0D)),conflict=unit(signals.getOrDefault("faction_conflict",0D));return candidates.stream().map(actor->registry.get(actor).map(s->{double ambition=unit(s.social("ambition")),morality=unit(s.social("morality")),influence=unit(s.social("influence")),fear=unit(s.social("fear")),score=unit(ambition*.32D+(1D-morality)*.24D+influence*.18D+(1D-fear)*.08D+crisis*.10D+conflict*.08D);return new AntagonistCandidate(actor,score,"emergent_antagonist",Map.of("ambition",Double.toString(ambition),"morality",Double.toString(morality)));}).orElse(new AntagonistCandidate(actor,0D,"unknown_actor",Map.of()))).filter(c->c.score()>=.55D).sorted(Comparator.comparingDouble(AntagonistCandidate::score).reversed()).toList();}private static double unit(double v){return Math.max(0D,Math.min(1D,v));}}
